class AVACalcSalesQuotationLineBestPrice    extends AVACalcSalesQuotationLine
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dataContract">_contract</param>
public void processOperation(AVACalcSalesQuotationLineBestPriceContract     _dataContract)
{
    AVACalcSalesQuotationLineBestPriceContract contract = _datacontract;
    QuotationId                            quotationId = contract.parmQuotationId();

    while select salesQuotationLine
        where salesQuotationLine.QuotationId == quotationId
    {
        //if (salesQuotationLine.SalesPrice > salesQuotationLine.AVABestPrice)
        if (salesQuotationLine.AVABestPrice && salesQuotationLine.SalesPrice > salesQuotationLine.AVABestPrice)
        {
            salesQuotationLine.SalesPrice = salesQuotationLine.AVABestPrice;
        }

        this.updateQuotationLineFields();
        ttsbegin;
        salesQuotationLine.selectForUpdate(true);
        salesQuotationLine.doUpdate();
        ttscommit;
    }

    this.updateLVPostion(quotationId);
}
